{
  "objectives": [
    {
      "level": "primary",
      "text": "To compare OS for patients with recurrent or metastatic cervical cancer who have histology of squamous cell carcinoma (SCC) and who have any eligible histology, treated with either cemiplimab or investigator’s choice (IC) chemotherapy.",
      "quote": "To compare OS for patients with recurrent or metastatic cervical cancer who have histology of squamous cell carcinoma (SCC) and who have any eligible histology, treated with either cemiplimab or investigator’s choice (IC) chemotherapy.",
      "endpoints": [
        {
          "text": "Overall survival (OS), defined as the time from randomization to the date of death.",
          "measure": "Overall survival",
          "timepoints_weeks": [],
          "quote": "The primary endpoint is OS, defined as the time from randomization to the date of death."
        }
      ]
    },
    {
      "level": "secondary",
      "text": "To compare progression-free survival (PFS) of cemiplimab versus IC chemotherapy",
      "quote": "To compare progression-free survival (PFS) of cemiplimab versus IC chemotherapy",
      "endpoints": [
        {
          "text": "Progression-free survival (PFS) per RECIST 1.1, defined as time from randomization to first documented tumor progression or death due to any cause.",
          "measure": "Progression-free survival",
          "timepoints_weeks": [],
          "quote": "The key secondary endpoints are PFS and ORR."
        }
      ]
    },
    {
      "level": "secondary",
      "text": "To compare objective response rate (ORR) (partial response [PR] + CR) of cemiplimab versus IC chemotherapy per Response Evaluation Criteria in Solid Tumors (RECIST) 1.1",
      "quote": "To compare objective response rate (ORR) (partial response [PR] + CR) of cemiplimab versus IC chemotherapy per Response Evaluation Criteria in Solid Tumors (RECIST) 1.1",
      "endpoints": [
        {
          "text": "Objective response rate (ORR) defined as the number of patients with a best overall response of confirmed CR or PR divided by the number of patients in the efficacy analysis set.",
          "measure": "Objective response rate",
          "timepoints_weeks": [],
          "quote": "Overall response rate will be defined as the number of patients with a best overall response of confirmed CR or PR divided by the number of patients in the efficacy analysis set."
        }
      ]
    },
    {
      "level": "secondary",
      "text": "To compare the duration of response (DOR) of cemiplimab versus IC chemotherapy",
      "quote": "To compare the duration of response (DOR) of cemiplimab versus IC chemotherapy",
      "endpoints": [
        {
          "text": "Duration of response (DOR) defined as the time between the date of first response (CR or PR) to the date of the first documented tumor progression (per RECIST 1.1) or death due to any cause.",
          "measure": "Duration of response",
          "timepoints_weeks": [],
          "quote": "Duration of response will be defined as the time between the date of first response (CR or PR) to the date of the first documented tumor progression (per RECIST 1.1) or death due to any cause."
        }
      ]
    },
    {
      "level": "secondary",
      "text": "To compare the safety profiles of cemiplimab versus IC chemotherapy by describing adverse events (AE)",
      "quote": "To compare the safety profiles of cemiplimab versus IC chemotherapy by describing adverse events (AE)",
      "endpoints": [
        {
          "text": "Safety and tolerability assessed by incidence of AEs, SAEs, deaths, and laboratory abnormalities.",
          "measure": "Safety and tolerability",
          "timepoints_weeks": [],
          "quote": "To evaluate the safety and tolerability of cemiplimab IC chemotherapy, the incidence of AEs, serious adverse events (SAEs), deaths, and laboratory abnormalities will be assessed."
        }
      ]
    },
    {
      "level": "secondary",
      "text": "To compare quality of life (QOL) for patients treated with cemiplimab versus IC chemotherapy using European Organization for Research and Treatment of Cancer Quality of Life Questionnaire-Core 30 (EORTC QLQ-C30)",
      "quote": "To compare quality of life (QOL) for patients treated with cemiplimab versus IC chemotherapy using European Organization for Research and Treatment of Cancer Quality of Life Questionnaire-Core 30 (EORTC QLQ-C30)",
      "endpoints": [
        {
          "text": "Quality of life measured by EORTC QLQ-C30.",
          "measure": "Quality of life",
          "timepoints_weeks": [],
          "quote": "Quality of life will be measured by the EORTC QLQ-C30."
        }
      ]
    },
    {
      "level": "secondary",
      "text": "To measure concentrations of cemiplimab in serum and characterize the pharmacokinetics (PK) of cemiplimab",
      "quote": "To measure concentrations of cemiplimab in serum and characterize the pharmacokinetics (PK) of cemiplimab",
      "endpoints": [
        {
          "text": "Cemiplimab concentrations in serum at multiple time points; PK variables including Cend of infusion and Ctrough.",
          "measure": "Pharmacokinetics",
          "timepoints_weeks": [],
          "quote": "Cemiplimab concentrations in the serum will be assessed at multiple time points throughout the treatment and follow-up periods."
        }
      ]
    },
    {
      "level": "secondary",
      "text": "To assess the immunogenicity of cemiplimab",
      "quote": "To assess the immunogenicity of cemiplimab",
      "endpoints": [
        {
          "text": "Anti-drug antibody (ADA) status and titer, including treatment-emergent and treatment-boosted responses.",
          "measure": "Immunogenicity",
          "timepoints_weeks": [],
          "quote": "Anti-drug antibody (ADA) variables include status of ADA response and titer as follows:"
        }
      ]
    },
    {
      "level": "secondary",
      "text": "To explore associations between the clinical efficacy of cemiplimab and molecular features in pretreatment tumor samples",
      "quote": "To explore associations between the clinical efficacy of cemiplimab and molecular features in pretreatment tumor samples",
      "endpoints": [
        {
          "text": "Relationships between efficacy endpoints and candidate biomarkers in tumor.",
          "measure": "Biomarker associations",
          "timepoints_weeks": [],
          "quote": "Relationships between efficacy endpoints and candidate biomarkers in tumor and peripheral blood will be described."
        }
      ]
    },
    {
      "level": "secondary",
      "text": "To explore the pharmacodynamic activity of cemiplimab on the immune system in peripheral blood samples",
      "quote": "To explore the pharmacodynamic activity of cemiplimab on the immune system in peripheral blood samples",
      "endpoints": [
        {
          "text": "Relationships between efficacy endpoints and candidate biomarkers in peripheral blood.",
          "measure": "Pharmacodynamic activity",
          "timepoints_weeks": [],
          "quote": "Relationships between efficacy endpoints and candidate biomarkers in tumor and peripheral blood will be described."
        }
      ]
    }
  ]
}
